# region: render
def render(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: emit
def emit(xs, limit=12):
    return [v if v <= limit else limit for v in xs[1:]]

# region: shape
def shape(xs, factor=3):
    return [v * factor for v in xs]

# region: digest
def digest(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: intake
def intake(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return intake(digest(shape(emit(render(raw)))))

